head.script:
scwin.simulateWrapper = function(target, type, options) {
	WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
	scwin.simulateWrapper('#cbo_CselCd_input', 'key-sequence', {
		sequence: '53'
	});
}
scwin.setSimulate2 = function() {
	scwin.simulateWrapper('#cbo_CselCd_input', 'key-combo', {
		combo: 'DOWN_ARROW'
	});
}		
scwin.setSimulate3 = function() {
	scwin.simulateWrapper('#cbo_CselCd_itemTable_0', 'key-combo', {
		combo: 'ENTER'
	});
}		
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('cbo_CselCd_label').click()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#cbo_CselCd_input').val('')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 1. '53' 에 해당하는 데이터가 리스트에 출력된다.
    //1. Data corresponding to '53' is output to the list.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#cbo_CselCd_input').val() == '53'", "true");
    //Test step 2. 키보드 아래버튼을 누른다.
    //2. Press the button below the keyboard.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 2. 출력된 데이터리스트에서 이동된다.
    //2. It is moved from the list of output data.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#cbo_CselCd_input').val() == '53010101 : 53010101 : '", "true");
    //Test step 3. 임의의 데이터를 선택하고 엔터버튼을누른다.
    //3. Select any data and press the Enter button.
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate3()");
    WebSquare.wUnit.addCommand("pause", "100");
    //Verify step 3. 임의의 데이터가 선택된다.
    //3. Any data is selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('cbo_CselCd_label').innerText == '53010101 : 53010101 :'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    /*
    	7/22 엔진부터 searchbox 에 값을 입력하여 아이템 리스트 팝업후 방향키로 선택시 첫번째 아이템이 무조건 선택됨
    	WPF-1157 [휠라코리아] autoComplete searchTarget="both" 일때 label 검색 후 엔터 입력시 검색데이터와는 상관없이 첫번째 값 선택됨
    */
    dl_cbo_CselCd.setData(['53010101', '', '53030101', '']);
    //cbo_CselCd.setItemSet("data:dl_cbo_CselCd","FULL_NM","CODE")
    cbo_CselCd.setNodeSet("data:dl_cbo_CselCd", "FULL_NM", "CODE");
}
